@@ -0,0 +1,238 @@
+'use client';
+
+import { useEffect } from 'react';
+import Link from 'next/link';
+import Image from 'next/image';
+import { useTranslations } from 'next-intl';
+import { useQuery } from '@tanstack/react-query';
+import { ExternalLink, Image as ImageIcon, Type, Video } from 'lucide-react';
+import mixpanel from 'mixpanel-browser';
+import { UIMessage } from 'ai';
+
+import createLogger from '@/lib/logger';
+import { extractSuggestedTools } from '@/utils/chat';
+import { CANVAS_CHAT_TOOL_NAMES } from '@/constants/chat';
+
+const MAX_SUGGESTED_TOOLS = 3;
+const AI_TOOLS_API_PATH = '/api/ai-tools';
+const QUERY_KEY_AI_TOOLS_BY_IDENTIFIERS = 'ai-tools-by-identifiers';
+const logger = createLogger('suggested-tools-for-message');
+
+export interface AiToolCardItem {
+  id: string;
+  name: string;
+  description: string | null;
+  slug: string | null;
+  outputType?: string;
+  backgroundImage?: string | null;
+  backgroundVideo?: string | null;
+}
+
+export interface SuggestedToolsForMessageProps {
+  message: UIMessage & { suggestedToolIds?: string[] | null };
+  locale: string;
+}
+
+/**
+ * Get suggested tool IDs or slugs from message.
+ * Prefer: suggestedToolIds → searchAiTool result in parts → SUGGESTED_TOOLS in content.
+ *
+ * @param message - Chat message possibly containing suggested tool identifiers
+ * @returns Up to MAX_SUGGESTED_TOOLS identifiers, or null if none found
+ */
+function getSuggestedToolIdentifiers(
+  message: UIMessage & { suggestedToolIds?: string[] | null }
+): string[] | null {
+  const fromPersisted = message.suggestedToolIds;
+  if (Array.isArray(fromPersisted) && fromPersisted.length > 0) {
+    return fromPersisted.slice(0, MAX_SUGGESTED_TOOLS);
+  }
+  const parts = message.parts;
+  if (Array.isArray(parts)) {
+    for (const part of parts) {
+      if (
+        part &&
+        typeof part === 'object' &&
+        'type' in part &&
+        part.type === 'tool-invocation' &&
+        'toolInvocation' in part
+      ) {
+        const inv = (part as {
+          toolInvocation?: { toolName?: string; result?: unknown };
+        }).toolInvocation;
+        if (
+          inv?.toolName === CANVAS_CHAT_TOOL_NAMES.SEARCH_AI_TOOL &&
+          inv.result &&
+          typeof inv.result === 'object' &&
+          'toolIds' in inv.result
+        ) {
+          const ids = (inv.result as { toolIds?: string[] }).toolIds;
+          if (Array.isArray(ids) && ids.length > 0) {
+            return ids.slice(0, MAX_SUGGESTED_TOOLS);
+          }
+        }
+      }
+    }
+  }
+  const slugs = extractSuggestedTools(message.content || '');
+  if (slugs && slugs.length > 0) {
+    return slugs.slice(0, MAX_SUGGESTED_TOOLS);
+  }
+  return null;
+}
+
+function outputIcon(outputType: string | undefined) {
+  switch (outputType) {
+    case 'IMAGE':
+      return <ImageIcon className="h-3.5 w-3.5" />;
+    case 'VIDEO':
+      return <Video className="h-3.5 w-3.5" />;
+    default:
+      return <Type className="h-3.5 w-3.5" />;
+  }
+}
+
+export function SuggestedToolsForMessage({
+  message,
+  locale
+}: SuggestedToolsForMessageProps) {
+  const t = useTranslations('Canvas.chat');
+  const identifiers = getSuggestedToolIdentifiers(message);
+
+  const { data, isLoading, isError, error } = useQuery<{
+    success: boolean;
+    data: AiToolCardItem[];
+  }>({
+    queryKey: [QUERY_KEY_AI_TOOLS_BY_IDENTIFIERS, identifiers?.join(',') ?? ''],
+    queryFn: async () => {
+      const params = new URLSearchParams({
+        locale,
+        slugs: (identifiers ?? []).join(',')
+      });
+      const res = await fetch(`${AI_TOOLS_API_PATH}?${params}`);
+      if (!res.ok) {
+        const fallbackMessage = 'Failed to fetch tools';
+        let message = fallbackMessage;
+        try {
+          const body = await res.json();
+          if (body && typeof body.error === 'string') message = body.error;
+        } catch {
+          // non-JSON or empty body
+        }
+        throw new Error(message);
+      }
+      const raw = await res.json();
+      if (
+        !raw ||
+        typeof raw !== 'object' ||
+        !Array.isArray(raw.data) ||
+        raw.success !== true
+      ) {
+        throw new Error('Invalid tools response');
+      }
+      return { success: true, data: raw.data };
+    },
+    enabled: !!identifiers && identifiers.length > 0,
+    retry: 1,
+    staleTime: 60_000
+  });
+
+  useEffect(() => {
+    if (isError && error) {
+      logger.error(
+        'Failed to fetch suggested AI tools',
+        error instanceof Error ? error : { cause: String(error) }
+      );
+    }
+  }, [isError, error]);
+
+  const tools = (data?.data ?? []).slice(0, MAX_SUGGESTED_TOOLS);
+
+  if (isLoading) {
+    return (
+      <div
+        className="mt-3 space-y-2"
+        aria-busy="true"
+        aria-label={t('suggestedTools.title')}
+      >
+        <p className="text-xs font-medium text-muted-foreground">
+          {t('suggestedTools.title')}
+        </p>
+        <div className="flex flex-col gap-2">
+          {[1, 2, 3].map((i) => (
+            <div
+              key={i}
+              className="h-14 animate-pulse rounded-lg border bg-muted"
+              aria-hidden="true"
+            />
+          ))}
+        </div>
+      </div>
+    );
+  }
+
+  if (isError || tools.length === 0) return null;
+
+  return (
+    <div className="mt-3 space-y-2">
+      <p className="text-xs font-medium text-muted-foreground">
+        {t('suggestedTools.title')}
+      </p>
+      <div className="flex flex-col gap-2">
+        {tools.map((tool) => {
+          const slug = tool.slug ?? tool.id;
+          const href = `/${locale}/ai-tools/${slug}`;
+          return (
+            <Link
+              key={tool.id}
+              href={href}
+              target="_blank"
+              rel="noopener noreferrer"
+              aria-label={`${tool.name} - ${t('suggestedTools.openInNewTab')}`}
+              className="relative flex items-center gap-2 rounded-lg border bg-card px-2.5 py-2 text-foreground shadow-sm hover:bg-accent/50"
+              onClick={() => {
+                mixpanel.track('[AiTool] Open from Canvas Chat', {
+                  source: 'canvas_chat_suggested_tools',
+                  aiToolId: tool.id,
+                  slug: tool.slug ?? tool.id,
+                  toolName: tool.name
+                });
+              }}
+            >
+              <div className="absolute left-2 top-2 flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-gray-100 text-muted-foreground">
+                {outputIcon(tool.outputType)}
+              </div>
+              <div className="relative h-12 w-12 shrink-0 overflow-hidden rounded-md bg-muted">
+                {tool.backgroundImage ? (
+                  <Image
+                    src={tool.backgroundImage}
+                    alt=""
+                    width={48}
+                    height={48}
+                    className="h-full w-full object-cover"
+                    unoptimized
+                  />
+                ) : (
+                  <div className="h-full w-full bg-muted" aria-hidden="true" />
+                )}
+              </div>
+              <div className="min-w-0 flex-1 flex flex-col gap-0.5">
+                <div className="flex items-center gap-1.5">
+                  <span className="text-sm font-medium text-foreground truncate">
+                    {tool.name}
+                  </span>
+                </div>
+                {tool.description && (
+                  <p className="text-xs text-muted-foreground line-clamp-2">
+                    {tool.description}
+                  </p>
+                )}
+              </div>
+              <ExternalLink className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
+            </Link>
+          );
+        })}
+      </div>
+    </div>
+  );
+}
