+      id: true,
+      name: true,
+      description: true,
+      slug: true,
+      executorType: true,
+      parameterSchema: true,
+      outputType: true,
+      defaultLanguage: true,
+      translations: true,
+      tags: {
+        select: { tag: { select: { id: true, name: true } } }
+      }
+    }
+  });
+
+  return rows.map((tool) => {
+    const inputTypes = {
+      hasImage: false,
+      hasText: false,
+      hasVideo: false,
+      hasRequiredImage: false,
+      hasRequiredText: false,
+      hasRequiredVideo: false
+    };
+    try {
+      if (tool.parameterSchema) {
+        const schema =
+          typeof tool.parameterSchema === 'string'
+            ? JSON.parse(tool.parameterSchema as string)
+            : tool.parameterSchema;
+        if (tool.executorType === 'GEMINI' && Array.isArray(schema)) {
+          const fields = schema as Array<{ type?: string; require?: boolean }>;
+          fields.forEach((field) => {
+            const isRequired = field.require ?? false;
+            if (field.type === 'image') {
+              inputTypes.hasImage = true;
+              if (isRequired) inputTypes.hasRequiredImage = true;
+            } else if (field.type === 'text') {
+              inputTypes.hasText = true;
+              if (isRequired) inputTypes.hasRequiredText = true;
+            } else if (field.type === 'video') {
+              inputTypes.hasVideo = true;
+              if (isRequired) inputTypes.hasRequiredVideo = true;
+            }
+          });
+        } else if (typeof schema === 'object' && schema !== null) {
+          const properties = (schema as { properties?: Record<string, unknown> }).properties;
+          const required = (schema as { required?: string[] }).required || [];
+          if (properties) {
+            Object.entries(properties).forEach(([key, prop]) => {
+              const propObj = prop as { type?: string; format?: string };
+              const isRequired = required.includes(key);
+              if (propObj.type === 'string' && propObj.format === 'data-url') {
+                inputTypes.hasImage = true;
+                if (isRequired) inputTypes.hasRequiredImage = true;
+              } else if (propObj.type === 'string' && (propObj.format === 'video-url' || key.toLowerCase().includes('video'))) {
