+'use client';
+
+import { UIMessage } from 'ai';
+
+import { extractSuggestedReplies } from '@/utils/chat';
+
+import { SuggestionReplyButton } from './suggestion-reply-button';
+
+const MAX_SUGGESTED_REPLIES_DISPLAY = 5;
+
+export interface SuggestedRepliesForMessageProps {
+  message: UIMessage;
+  onSuggestionClick: (suggestion: string) => void;
+  disabled: boolean;
+}
+
+export function SuggestedRepliesForMessage({
+  message,
+  onSuggestionClick,
+  disabled
+}: SuggestedRepliesForMessageProps) {
+  const content = message.content || '';
+  const extracted = extractSuggestedReplies(content);
+  const suggestedReplies = (extracted ?? []).slice(
+    0,
+    MAX_SUGGESTED_REPLIES_DISPLAY
+  );
+
+  if (suggestedReplies.length === 0) return null;
+
+  return (
+    <div className="mt-3 flex flex-wrap gap-2">
+      {suggestedReplies.map((suggestion, index) => (
+        <SuggestionReplyButton
+          key={`suggestion-${index}`}
+          suggestion={suggestion}
+          onClick={onSuggestionClick}
+          disabled={disabled}
+        />
+      ))}
+    </div>
+  );
+}
